//! Test that C++ overloads for [std::list][list] can be successfully represented in Rust.
//!
//! [list]: https://en.cppreference.com/cpp/container/list

#![allow(unused_braces, reason = "Generated by overload! macro")]

use cpp::cpp;
use splat_overload::overload;
use std::ffi::{c_size_t, c_void};
use std::marker::PhantomData;

// C++ header includes
cpp! {{
    #include <list>
    #include <vector>
    #include <ranges>
    #include <algorithm>
    #include <iterator>
    #include <cstddef>

    // The `cpp!` macro can't handle C/C++ function type syntax, so we have to declare function
    // types here.
    typedef bool LessThanPredicateCpp(const int&, const int&);
}}

/// An ABI-compatible Rust function type for `LessThanPredicateCpp`.
pub type LessThanPredicateRust = extern "C" fn(&T, &T) -> bool;

/// A wrapper struct to hold the returned C++ `std::list<int>` pointer.
///
/// ### Limitations
///
/// This struct and the impl should be fully generic over the list type.
/// FIXME: make the `overload!` macro support generics.
#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
pub struct StdList(*mut c_void, PhantomData<T>);

/// Workaround for missing generic support in the `overload!` macro.
pub type T = std::ffi::c_int;

/// A wrapper struct to hold a C++ `std::list<int>::const_iterator` object.
/// `insert`, `erase` and `splice` all take `const_iterator`, so there is no mutable version.
///
/// ### Limitations
///
/// Unlike `StdForwardListIter`, this doesn't borrow the list. If it did, you couldn't call
/// `insert(&mut self, pos, ...)` while holding `pos`.
///
/// The downside: Rust can't stop you passing an iterator to the wrong list, or using one after
/// its element is erased. C++ doesn't stop that either.
///
/// ### Potential Resolutions
///
/// A cursor that holds the `&mut` borrow, like Rust's unstable `LinkedList::cursor_front_mut()`.
/// But then `insert` is a cursor method, not a list overload.
#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
pub struct StdListIter(*mut c_void, PhantomData<*const T>);

#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
impl StdListIter {
    /// Returns the element at the current iterator position.
    ///
    /// ### Safety
    ///
    /// Accessing `end` iterators, or any invalid iterator, is undefined behaviour.
    unsafe fn access(&self) -> T {
        let iter = self.0 as *const c_void;
        unsafe {
            cpp!([iter as "std::list<int>::const_iterator"] -> T as "int" {
                return *iter;
            })
        }
    }

    /// Returns an iterator to the next position in the list.
    /// Advancing an `end` iterator is undefined behaviour.
    fn next_iter(&self) -> StdListIter {
        let iter = self.0 as *const c_void;
        let next = unsafe {
            cpp!([iter as "std::list<int>::const_iterator"] -> *mut c_void as "std::list<int>::const_iterator" {
                return std::next(iter);
            })
        };
        StdListIter(next, PhantomData)
    }
}

// The cpp! macro doesn't work inside the overload! macro, so we extract C++ calls into separate methods.
// A mature overload feature (or a production C++ project) wouldn't need this impl block.
#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
#[allow(
    non_upper_case_globals,
    reason = "Triggered by cpp! macro in rust-analyzer"
)]
impl StdList {
    // Constructors: internal C++ implementations for `new(...)` overloads
    fn default() -> StdList {
        let list = unsafe {
            cpp!([] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>();
            })
        };
        StdList(list, PhantomData)
    }

    fn repeat_default(count: c_size_t) -> StdList {
        let list = unsafe {
            cpp!([count as "size_t"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>(count);
            })
        };
        StdList(list, PhantomData)
    }

    fn repeat_value(count: c_size_t, value: T) -> StdList {
        let list = unsafe {
            cpp!([count as "size_t", value as "int"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>(count, value);
            })
        };
        StdList(list, PhantomData)
    }

    /// Construct a list from a C++ iterator range `[first, last)`, excluding the element at `last`.
    fn from_cpp_iter(first: &StdListIter, last: &StdListIter) -> StdList {
        let first = first.0 as *const c_void;
        let last = last.0 as *const c_void;
        // SAFETY: an empty C++ range is fine, unlike an empty Rust slice.
        let list = unsafe {
            cpp!([first as "std::list<int>::const_iterator", last as "std::list<int>::const_iterator"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>(first, last);
            })
        };
        StdList(list, PhantomData)
    }

    /// ### Limitations
    ///
    /// A slice only covers items stored next to each other in memory. The C++ iterator constructor
    /// takes any input iterator, so a slice can't replace it. That's why we also have the
    /// `StdListIter` overload, which can copy from another list.
    fn from_slice(items: &[T]) -> StdList {
        // An empty Rust slice is guaranteed to have a dangling pointer, see
        // <https://doc.rust-lang.org/std/slice/fn.from_raw_parts.html#safety>
        if items.is_empty() {
            return StdList::default();
        }
        let len = items.len();
        let items: *const T = items.as_ptr();
        // SAFETY: items is a non-null pointer to len properly initialized values of T
        let list = unsafe {
            cpp!([items as "const int*", len as "size_t"] -> *mut c_void as "std::list<int>*" {
                // In C++, `items + len` increments the pointer by `len` elements of `sizeof(int)`.
                return new std::list<int>(items, items + len);
            })
        };
        StdList(list, PhantomData)
    }

    /// ### Limitations
    ///
    /// This implementation builds a Rust `Vec` and C++ `std::vector` from the iterator for simplicity.
    /// A production implementation could use a Rust-to-C++ iterator-to-range adapter.
    fn from_iter(iter: &mut dyn Iterator<Item = T>) -> StdList {
        let items: Vec<T> = iter.collect();
        // An empty Rust Vec is guaranteed to have a dangling pointer, see
        // <https://doc.rust-lang.org/std/vec/struct.Vec.html#method.as_ptr>
        if items.is_empty() {
            return StdList::default();
        }
        let len = items.len();
        let items: *const T = items.as_ptr();
        // SAFETY: items is a non-null pointer to len properly initialized values of T
        let list = unsafe {
            cpp!([items as "const int*", len as "size_t"] -> *mut c_void as "std::list<int>*" {
                std::vector<int> vec = std::vector<int>(items, items + len);
                #ifdef __cpp_lib_containers_ranges
                return new std::list<int>(std::from_range, vec);
                #else
                #error "std::from_range is not available, try using `-std=c++23` or a newer compiler"
                #endif
            })
        };
        StdList(list, PhantomData)
    }

    fn copy_from(other: &StdList) -> StdList {
        let other = other.0 as *const c_void;
        let list = unsafe {
            cpp!([other as "const std::list<int>*"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>(*other);
            })
        };
        StdList(list, PhantomData)
    }

    fn move_from(other: &mut StdList) -> StdList {
        let other: *mut c_void = other.0;
        let list = unsafe {
            cpp!([other as "std::list<int>*"] -> *mut c_void as "std::list<int>*" {
                // C++ guarantees that `other` is empty after this move.
                return new std::list<int>(std::move(*other));
            })
        };
        StdList(list, PhantomData)
    }

    /// ### Limitations
    ///
    /// These are just examples, a production implementation would support any number of arguments.
    fn from_initializer_list_1(a: T) -> StdList {
        let list = unsafe {
            cpp!([a as "int"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>{ a };
            })
        };
        StdList(list, PhantomData)
    }

    fn from_initializer_list_2(a: T, b: T) -> StdList {
        let list = unsafe {
            cpp!([a as "int", b as "int"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>{ a, b };
            })
        };
        StdList(list, PhantomData)
    }

    fn from_initializer_list_3(a: T, b: T, c: T) -> StdList {
        let list = unsafe {
            cpp!([a as "int", b as "int", c as "int"] -> *mut c_void as "std::list<int>*" {
                return new std::list<int>{ a, b, c };
            })
        };
        StdList(list, PhantomData)
    }

    // Iterators (not overloaded)
    //
    // The const/non-const `begin()` and `end()` overloads are already in `forward_list.rs`.

    /// Returns a constant iterator to the first element of the list.
    fn begin(&self) -> StdListIter {
        let slf = self.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "const std::list<int>*"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->cbegin();
            })
        };
        StdListIter(iter, PhantomData)
    }

    /// Returns a constant iterator to a placeholder "element" *after* the end of the list.
    /// Accessing this placeholder element is undefined behaviour.
    fn end(&self) -> StdListIter {
        let slf = self.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "const std::list<int>*"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->cend();
            })
        };
        StdListIter(iter, PhantomData)
    }

    // Modifiers: internal implementations for `insert(...)`
    fn insert_value(&mut self, pos: &StdListIter, value: T) -> StdListIter {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", value as "int"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->insert(pos, value);
            })
        };
        StdListIter(iter, PhantomData)
    }

    fn insert_repeat(&mut self, pos: &StdListIter, count: c_size_t, value: T) -> StdListIter {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", count as "size_t", value as "int"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->insert(pos, count, value);
            })
        };
        StdListIter(iter, PhantomData)
    }

    fn insert_cpp_iter(
        &mut self,
        pos: &StdListIter,
        first: &StdListIter,
        last: &StdListIter,
    ) -> StdListIter {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let first = first.0 as *const c_void;
        let last = last.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", first as "std::list<int>::const_iterator", last as "std::list<int>::const_iterator"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->insert(pos, first, last);
            })
        };
        StdListIter(iter, PhantomData)
    }

    fn insert_slice(&mut self, pos: &StdListIter, items: &[T]) -> StdListIter {
        // An empty Rust slice is guaranteed to have a dangling pointer.
        // C++ returns `pos` when nothing is inserted.
        if items.is_empty() {
            return StdListIter(pos.0, PhantomData);
        }
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let len = items.len();
        let items: *const T = items.as_ptr();
        // SAFETY: items is a non-null pointer to len properly initialized values of T
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", items as "const int*", len as "size_t"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->insert(pos, items, items + len);
            })
        };
        StdListIter(iter, PhantomData)
    }

    // Modifiers: internal implementations for `erase(...)`
    fn erase_one(&mut self, pos: StdListIter) -> StdListIter {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator"] -> *mut c_void as "std::list<int>::const_iterator" {
                // Avoid undefined behaviour when erasing `end()`.
                if (pos == slf->cend()) {
                    return slf->cend();
                }
                return slf->erase(pos);
            })
        };
        StdListIter(iter, PhantomData)
    }

    fn erase_range(&mut self, first: StdListIter, last: StdListIter) -> StdListIter {
        let slf: *mut c_void = self.0;
        let first = first.0 as *const c_void;
        let last = last.0 as *const c_void;
        let iter = unsafe {
            cpp!([slf as "std::list<int>*", first as "std::list<int>::const_iterator", last as "std::list<int>::const_iterator"] -> *mut c_void as "std::list<int>::const_iterator" {
                return slf->erase(first, last);
            })
        };
        StdListIter(iter, PhantomData)
    }

    // Modifiers: internal implementations for `splice(...)`
    fn splice_all(&mut self, pos: &StdListIter, other: &mut StdList) {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let other: *mut c_void = other.0;
        unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", other as "std::list<int>*"] {
                slf->splice(pos, *other);
            })
        }
    }

    fn splice_one(&mut self, pos: &StdListIter, other: &mut StdList, it: &StdListIter) {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let other: *mut c_void = other.0;
        let it = it.0 as *const c_void;
        unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", other as "std::list<int>*", it as "std::list<int>::const_iterator"] {
                slf->splice(pos, *other, it);
            })
        }
    }

    fn splice_range(
        &mut self,
        pos: &StdListIter,
        other: &mut StdList,
        first: &StdListIter,
        last: &StdListIter,
    ) {
        let slf: *mut c_void = self.0;
        let pos = pos.0 as *const c_void;
        let other: *mut c_void = other.0;
        let first = first.0 as *const c_void;
        let last = last.0 as *const c_void;
        unsafe {
            cpp!([slf as "std::list<int>*", pos as "std::list<int>::const_iterator", other as "std::list<int>*", first as "std::list<int>::const_iterator", last as "std::list<int>::const_iterator"] {
                slf->splice(pos, *other, first, last);
            })
        }
    }

    // Transforms: internal implementations for `sort(...)`
    fn sort_less_than(&mut self) {
        let slf: *mut c_void = self.0;
        unsafe {
            cpp!([slf as "std::list<int>*"] {
                slf->sort();
            })
        }
    }

    fn sort_with(&mut self, less_than_predicate: LessThanPredicateRust) {
        let slf: *mut c_void = self.0;
        unsafe {
            // Function types are function pointers in Rust, but in C++ function types are objects,
            // so we need to convert the Rust type to a C++ pointer to function type.
            cpp!([slf as "std::list<int>*", less_than_predicate as "LessThanPredicateCpp*"] {
                slf->sort(less_than_predicate);
            })
        }
    }

    // List checks (not overloaded)
    fn len(&self) -> c_size_t {
        let slf = self.0 as *const c_void;
        unsafe {
            cpp!([slf as "const std::list<int>*"] -> c_size_t as "size_t" {
                return slf->size();
            })
        }
    }

    /// Copy the list into a `Vec`, so tests can check every item.
    fn to_vec(&self) -> Vec<T> {
        let len = self.len();
        let mut items: Vec<T> = Vec::with_capacity(len);
        // An empty Rust Vec is guaranteed to have a dangling pointer.
        if len == 0 {
            return items;
        }
        let slf = self.0 as *const c_void;
        let out: *mut T = items.as_mut_ptr();
        // SAFETY: out is a non-null pointer to space for len values of T
        unsafe {
            cpp!([slf as "const std::list<int>*", out as "int*"] {
                std::copy(slf->cbegin(), slf->cend(), out);
            });
            items.set_len(len);
        }
        items
    }
}

// Constructors: `new(...)`
//
// All 8 C++ constructors are wrapped, except the allocator versions (`list(alloc)`,
// `list(count, alloc)`, `list(other, alloc)` and so on). Those only add an allocator argument,
// so they're not interesting overloads to test.
overload! {
    impl StdList {
        /// Construct an empty list.
        pub fn new() -> StdList {
            StdList::default()
        }

        /// Construct a list with `count` default-constructed items.
        pub fn new(count: c_size_t) -> StdList {
            StdList::repeat_default(count)
        }

        /// Construct a list filled with `count` instances of the given value.
        pub fn new(count: c_size_t, value: T) -> StdList {
            StdList::repeat_value(count, value)
        }

        /// Construct a list by copying items from a slice.
        pub fn new(items: &[T]) -> StdList {
            StdList::from_slice(items)
        }

        /// Construct a list from a C++ iterator range `[first, last)`, excluding the element at `last`.
        pub fn new(first: &StdListIter, last: &StdListIter) -> StdList {
            StdList::from_cpp_iter(first, last)
        }

        /// Construct a list from an iterator, like C++23 `list(std::from_range, range)`.
        ///
        /// ### Limitations
        ///
        /// The `overload!` macro doesn't support generics in this position yet, so we use
        /// `dyn Trait` instead.
        pub fn new(iter: &mut dyn Iterator<Item = T>) -> StdList {
            StdList::from_iter(iter)
        }

        /// Clone list items into a new list from a shared list reference.
        pub fn new(other: &StdList) -> StdList {
            StdList::copy_from(other)
        }

        /// Move list items into a new list from a mutable list reference.
        /// `other` is empty afterwards.
        ///
        /// ### Ergonomics
        ///
        /// Copy vs move is just `&` vs `&mut`. Easy to mix up, and you wouldn't expect `&mut`
        /// to empty the list.
        pub fn new(other: &mut StdList) -> StdList {
            StdList::move_from(other)
        }

        /// Construct a list from the supplied items.
        ///
        /// ### Limitations
        ///
        /// Rust has no `initializer_list`, so we only support 1 to 3 items.
        ///
        /// These only compile because `T` is `c_int`. If `T` were `c_size_t`, `new(a)` would
        /// clash with `new(count)`, and `new(a, b)` with `new(count, value)`.
        ///
        /// ### Ergonomics
        ///
        /// C++ uses brackets to choose: `list<int>{3, 9}` vs `list<int>(3, 9)`. Rust only has the
        /// argument types, so `new(3, 9)` is `[3, 9]` but `new(3_usize, 9)` is `[9, 9, 9]`.
        /// Forget the suffix and you silently get the other overload.
        ///
        /// Callers also need `let list: StdList = StdList::new(...)`, because the return type
        /// isn't inferred. It should be, since every overload returns `StdList`.
        /// FIXME: fix the macro or `splat` compiler implementation so inference works here.
        pub fn new(a: T) -> StdList {
            StdList::from_initializer_list_1(a)
        }

        pub fn new(a: T, b: T) -> StdList {
            StdList::from_initializer_list_2(a, b)
        }

        pub fn new(a: T, b: T, c: T) -> StdList {
            StdList::from_initializer_list_3(a, b, c)
        }
    }
}

// Modifiers: `insert(...)`
//
// This covers all 5 C++ `insert` overloads. `insert(pos, const T&)` and `insert(pos, T&&)`
// become one Rust overload. C++23 `insert_range` has a different name, so it isn't part of
// this set.
overload! {
    impl StdList {
        /// Insert `value` before `pos`.
        /// Returns an iterator to the inserted element.
        pub fn insert(&mut self, pos: &StdListIter, value: T) -> StdListIter {
            self.insert_value(pos, value)
        }

        /// Insert `count` copies of `value` before `pos`.
        /// Returns an iterator to the first inserted element, or `pos` if `count` is zero.
        ///
        /// ### Ergonomics
        ///
        /// In C++, `insert(pos, 2, 20)` also matches the iterator range template, and the standard
        /// has a special rule to pick this one. Rust has no clash, but you need
        /// `insert(pos, 2_usize, 20)`.
        pub fn insert(&mut self, pos: &StdListIter, count: c_size_t, value: T) -> StdListIter {
            self.insert_repeat(pos, count, value)
        }

        /// Insert the elements from a C++ iterator range `[first, last)` before `pos`.
        /// Returns an iterator to the first inserted element, or `pos` if the range is empty.
        ///
        /// ### Limitations
        ///
        /// `first` and `last` must not point into this list. Rust can't check this.
        pub fn insert(&mut self, pos: &StdListIter, first: &StdListIter, last: &StdListIter) -> StdListIter {
            self.insert_cpp_iter(pos, first, last)
        }

        /// Insert the items from a slice before `pos`.
        /// Returns an iterator to the first inserted element, or `pos` if the slice is empty.
        ///
        /// ### Limitations
        ///
        /// This replaces C++ `insert(pos, initializer_list)`. We can't copy the constructors'
        /// 1/2/3 item overloads, because `insert(pos, a)` has the same types as
        /// `insert(pos, value)`.
        pub fn insert(&mut self, pos: &StdListIter, items: &[T]) -> StdListIter {
            self.insert_slice(pos, items)
        }
    }
}

// Modifiers: `erase(...)`
//
// C++ has 2 `erase` overloads, and both are wrapped.
overload! {
    impl StdList {
        /// Remove the element at `pos`.
        /// Returns an iterator to the element after the removed element.
        ///
        /// Erasing `end()` does nothing. (In C++ it's undefined behaviour.)
        ///
        /// ### Limitations
        ///
        /// `pos` is taken by value since it's invalid afterwards, but any copies of it aren't
        /// caught.
        pub fn erase(&mut self, pos: StdListIter) -> StdListIter {
            self.erase_one(pos)
        }

        /// Remove the elements in the range `[first, last)`.
        /// Returns `last`.
        ///
        /// ### Limitations
        ///
        /// `first` and `last` must point into this list, and `first` must come before `last`.
        /// Rust can't check either.
        pub fn erase(&mut self, first: StdListIter, last: StdListIter) -> StdListIter {
            self.erase_range(first, last)
        }
    }
}

// Modifiers: `splice(...)`
overload! {
    impl StdList {
        /// Move all the elements of `other` before `pos`. `other` is empty afterwards.
        ///
        /// ### Limitations
        ///
        /// C++ has 6 `splice` overloads: 3 shapes, each with `list&` and `list&&`. Both of those
        /// are `&mut StdList` in Rust, so only the 3 shapes are wrapped. They behave the same.
        ///
        /// C++ allows `other` to be the same list as `*this`. Rust doesn't, because that would be
        /// two `&mut` borrows of one list.
        ///
        /// Moved elements keep their iterators, but those iterators now point into `self`. Rust
        /// lifetimes can't move a borrow from one list to another.
        pub fn splice(&mut self, pos: &StdListIter, other: &mut StdList) {
            self.splice_all(pos, other)
        }

        /// Move the element at `it` in `other` before `pos`.
        pub fn splice(&mut self, pos: &StdListIter, other: &mut StdList, it: &StdListIter) {
            self.splice_one(pos, other, it)
        }

        /// Move the elements in the range `[first, last)` in `other` before `pos`.
        pub fn splice(&mut self, pos: &StdListIter, other: &mut StdList, first: &StdListIter, last: &StdListIter) {
            self.splice_range(pos, other, first, last)
        }
    }
}

// Transforms: `sort(...)`
//
// C++ has 2 `sort` overloads, and both are wrapped.
overload! {
    impl StdList {
        /// Sort the list in ascending order.
        pub fn sort(&mut self) {
            self.sort_less_than()
        }

        /// Sort the list using the given "less than" predicate.
        ///
        /// ### Limitations
        ///
        /// C++ takes any callable as a `Compare` template parameter. Here, it has to be an
        /// `extern "C" fn`, because:
        /// - the `overload!` macro doesn't support generics, so we can't take `impl Fn`
        /// - C++ templates are instantiated when the C++ code is compiled, so it can't be
        ///   instantiated for a Rust closure type anyway
        ///
        /// That means closures that capture variables can't be used. Non-capturing closures can't
        /// be used either, because they only coerce to Rust ABI `fn` pointers.
        ///
        /// If the predicate panics, the process aborts, because a panic can't unwind out of an
        /// `extern "C" fn`.
        ///
        /// ### Ergonomics
        ///
        /// Callers have to write a separate named `extern "C" fn`, even for a one-line comparison.
        /// Rust's own `Vec::sort_by` takes a closure, and returns an `Ordering` instead of a
        /// "less than" `bool`.
        ///
        /// ### Potential Resolutions
        ///
        /// Pass a C++ trampoline function plus a pointer to the Rust closure, so captures work.
        pub fn sort(&mut self, less_than_predicate: LessThanPredicateRust) {
            self.sort_with(less_than_predicate)
        }
    }
}

/// These tests show that the correct Rust and C++ overloads are being called.
#[test]
pub fn test_list_new() {
    let default_list: StdList = StdList::new();
    assert_eq!(default_list.to_vec(), []);

    // ### Ergonomics
    //
    // Easy to confuse with the one-item initializer list overload.
    //
    // These `StdList` type annotations are currently required, but inference should work.
    // FIXME: fix the macro or `splat` compiler implementation so inference works here.
    let repeat_default: StdList = StdList::new(3_usize);
    assert_eq!(repeat_default.to_vec(), [0, 0, 0]);

    // Swapped arguments, or the initializer list overload, would give a different list.
    let repeat_value: StdList = StdList::new(3_usize, 9);
    assert_eq!(repeat_value.to_vec(), [9, 9, 9]);

    // ### Limitations
    //
    // The `as_slice` call is required to match the overload, an array doesn't automatically coerce.
    let from_slice: StdList = StdList::new([5, 6, 7, 8].as_slice());
    assert_eq!(from_slice.to_vec(), [5, 6, 7, 8]);
    let from_empty_slice: StdList = StdList::new([].as_slice());
    assert_eq!(from_empty_slice.to_vec(), []);

    let from_cpp_iter: StdList = StdList::new(&from_slice.begin(), &from_slice.end());
    assert_eq!(from_cpp_iter.to_vec(), [5, 6, 7, 8]);
    let from_partial_cpp_iter: StdList =
        StdList::new(&from_slice.begin().next_iter(), &from_slice.end());
    assert_eq!(from_partial_cpp_iter.to_vec(), [6, 7, 8]);
    let from_empty_cpp_iter: StdList = StdList::new(&from_slice.end(), &from_slice.end());
    assert_eq!(from_empty_cpp_iter.to_vec(), []);

    // ### Limitations
    //
    // The cast is required to match the overload, an iterator doesn't automatically coerce.
    let mut iter: std::array::IntoIter<T, 3> = [1, 2, 3].into_iter();
    let from_iter: StdList = StdList::new(&mut iter as &mut dyn Iterator<Item = _>);
    assert_eq!(from_iter.to_vec(), [1, 2, 3]);
    let mut empty_iter: std::array::IntoIter<T, 0> = [].into_iter();
    let from_empty_iter: StdList = StdList::new(&mut empty_iter as &mut dyn Iterator<Item = _>);
    assert_eq!(from_empty_iter.to_vec(), []);

    let mut original: StdList = StdList::new([1, 2, 3].as_slice());
    let copied: StdList = StdList::new(&original);
    assert_eq!(copied.to_vec(), [1, 2, 3]);
    assert_eq!(original.to_vec(), [1, 2, 3]);
    let moved: StdList = StdList::new(&mut original);
    assert_eq!(moved.to_vec(), [1, 2, 3]);
    assert_eq!(original.to_vec(), []);

    let from_initializer_list: StdList = StdList::new(3);
    assert_eq!(from_initializer_list.to_vec(), [3]);
    let from_initializer_list: StdList = StdList::new(3, 9);
    assert_eq!(from_initializer_list.to_vec(), [3, 9]);
    let from_initializer_list: StdList = StdList::new(3, 9, 1);
    assert_eq!(from_initializer_list.to_vec(), [3, 9, 1]);
}

#[test]
pub fn test_list_insert() {
    let mut list: StdList = StdList::new([1, 2, 3].as_slice());

    // `pos` points at `2`, and stays valid after each insert.
    let pos = list.begin().next_iter();

    let inserted = list.insert(&pos, 10);
    assert_eq!(unsafe { inserted.access() }, 10);
    assert_eq!(list.to_vec(), [1, 10, 2, 3]);

    let inserted = list.insert(&pos, 2_usize, 20);
    assert_eq!(unsafe { inserted.access() }, 20);
    assert_eq!(list.to_vec(), [1, 10, 20, 20, 2, 3]);
    assert_eq!(unsafe { pos.access() }, 2);

    // ### Ergonomics
    //
    // `list.insert(&list.end(), ...)` doesn't compile, so we get `end` first.
    let other: StdList = StdList::new([7, 8].as_slice());
    let end = list.end();
    let inserted = list.insert(&end, &other.begin(), &other.end());
    assert_eq!(unsafe { inserted.access() }, 7);
    assert_eq!(list.to_vec(), [1, 10, 20, 20, 2, 3, 7, 8]);
    assert_eq!(other.to_vec(), [7, 8]);

    let begin = list.begin();
    let inserted = list.insert(&begin, [4, 5].as_slice());
    assert_eq!(unsafe { inserted.access() }, 4);
    assert_eq!(list.to_vec(), [4, 5, 1, 10, 20, 20, 2, 3, 7, 8]);

    // Inserting nothing returns `pos`.
    let inserted = list.insert(&pos, [].as_slice());
    assert_eq!(unsafe { inserted.access() }, 2);
    let inserted = list.insert(&pos, 0_usize, 99);
    assert_eq!(unsafe { inserted.access() }, 2);
    assert_eq!(list.to_vec(), [4, 5, 1, 10, 20, 20, 2, 3, 7, 8]);
}

#[test]
pub fn test_list_erase() {
    let mut list: StdList = StdList::new([1, 2, 3, 4, 5].as_slice());

    let second = list.begin().next_iter();
    let after = list.erase(second);
    assert_eq!(unsafe { after.access() }, 3);
    assert_eq!(list.to_vec(), [1, 3, 4, 5]);

    let first = list.begin();
    let last = first.next_iter().next_iter();
    let after = list.erase(first, last);
    assert_eq!(unsafe { after.access() }, 4);
    assert_eq!(list.to_vec(), [4, 5]);

    let end = list.end();
    list.erase(end);
    assert_eq!(list.to_vec(), [4, 5]);
}

#[test]
pub fn test_list_splice() {
    let mut list: StdList = StdList::new([1, 2, 3].as_slice());
    let mut other: StdList = StdList::new([10, 20].as_slice());
    let pos = list.begin().next_iter();
    list.splice(&pos, &mut other);
    assert_eq!(list.to_vec(), [1, 10, 20, 2, 3]);
    assert_eq!(other.to_vec(), []);

    let mut list: StdList = StdList::new([1, 2, 3].as_slice());
    let mut other: StdList = StdList::new([10, 20, 30].as_slice());
    let pos = list.end();
    let it = other.begin().next_iter();
    list.splice(&pos, &mut other, &it);
    assert_eq!(list.to_vec(), [1, 2, 3, 20]);
    assert_eq!(other.to_vec(), [10, 30]);
    // `it` now points into `list`.
    assert_eq!(unsafe { it.access() }, 20);

    let mut list: StdList = StdList::new([1, 2, 3].as_slice());
    let mut other: StdList = StdList::new([10, 20, 30, 40].as_slice());
    let pos = list.begin();
    let first = other.begin().next_iter();
    let last = other.end();
    list.splice(&pos, &mut other, &first, &last);
    assert_eq!(list.to_vec(), [20, 30, 40, 1, 2, 3]);
    assert_eq!(other.to_vec(), [10]);
}

#[test]
pub fn test_list_sort() {
    let mut list: StdList = StdList::new([3, 1, 2].as_slice());
    list.sort();
    assert_eq!(list.to_vec(), [1, 2, 3]);

    // This predicate is deliberately inverted.
    extern "C" fn more_than_predicate(a: &T, b: &T) -> bool {
        a > b
    }
    let mut list: StdList = StdList::new([3, 1, 2].as_slice());
    list.sort(more_than_predicate);
    assert_eq!(list.to_vec(), [3, 2, 1]);
}
